from http.server import HTTPServer, BaseHTTPRequestHandler
import sys
import json

request_count = 0


class Handler(BaseHTTPRequestHandler):
    def _handle(self):
        global request_count
        request_count += 1

        if self.path == "/health" and self.command == "GET":
            self._send(200, "ok")
        elif self.path == "/echo" and self.command == "POST":
            body = self.rfile.read()
            self._send(200, body)
        elif self.path == "/count" and self.command == "GET":
            self._send(200, str(request_count - 1))
        else:
            self._send(404, json.dumps({"error": "not found"}))

    def _send(self, status, body):
        if isinstance(body, str):
            body = body.encode()
        self.send_response(status)
        self.send_header("Content-Type", "text/plain" if isinstance(body, bytes) and b"<" not in body[:1] else "application/json")
        if status != 404:
            self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.end_headers()
        self.wfile.write(body)

    do_GET = lambda self: self._handle()
    do_POST = lambda self: self._handle()


if __name__ == "__main__":
    port = int(sys.argv[1])
    print(f"Serving on port {port}")
    HTTPServer(("0.0.0.0", port), Handler).serve_forever()
